 12	export function resolveQuaestioInput(
 13	  filePath: string | undefined,
 14	  positionals: string[],
 15	): QuaestioInput {
 16	  if (filePath !== undefined) {
 17	    if (positionals.length > 0)
 18	      return { ok: false, error: "pass the quaestio inline OR with --file, not both" };
 19	    return { ok: true, source: "file", path: filePath };
 20	  }
 21	  if (positionals.length === 0) return { ok: false, error: "no quaestio given" };
 22	  if (positionals.length > 1)
 23	    return {
 24	      ok: false,
 25	      error: `unexpected extra arguments — did you forget to quote the quaestio? (${positionals.join(" ")})`,
 26	    };
 27	  return { ok: true, source: "inline", text: positionals[0] };
 28	}
